const state = { user: null, csrf: null, workspacePreview:false, workspaceOwnerName:"", teamMessages:[], messagePollTimer:null, designations:[], accessFeatures:[], dataAccessOptions:[], page: "overview", overviewPreset:"30d", overviewFrom:"", overviewTo:"", targetsMonth:"", targetData:null, collectionView:"all", collectionBatch:"all", collectionCourse:"all", financeSection:"overview", financeDays:30, financePastDueDays:30, financeUpcomingDays:30, followupFilter:"action", followupDetailOpen:null, collectionDueView:"month", collectionDueMonth:"", incentiveView:"overview", incentivePerson:null, incentivePayoutFilter:"unpaid", incentiveFrom:"", incentiveTo:"", incentiveDueFrom:"", incentiveDueTo:"", incentiveRules:{pool_rate:5,rep_rate:2,manager_rate:3,payout_due_days:30}, reportMonths:12, reportRange:"30d", reportFrom:"", reportTo:"", reportGroup:"day", data: {}, commonDataPromises: {}, settings: {}, products: [], batches: [], orders: [], installments: [], team: [] };
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const moneyFormatters = new Map();
const money = (n) => {
  if (n===undefined||n===null) return "Hidden";
  const currency=state.settings.currency||"INR";
  if (!moneyFormatters.has(currency)) moneyFormatters.set(currency,new Intl.NumberFormat("en-IN", { style: "currency", currency, maximumFractionDigits: 2 }));
  return moneyFormatters.get(currency).format(Number(n||0));
};
const canViewData = (key) => state.user?.role==="owner" || (state.user?.data_permissions||[]).includes(key);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const day = (s) => s ? new Date(`${s}T00:00:00`).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }) : "—";
const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; };
const addMonthsIso = (iso, count) => { const [y,m,d]=String(iso||today()).split("-").map(Number); const first=new Date(y,m-1+count,1); const last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(); return `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,"0")}-${String(Math.min(d,last)).padStart(2,"0")}`; };
const titleCase = (s) => String(s || "").replaceAll("_", " ").replace(/\b\w/g, x => x.toUpperCase());

const readCache=new Map();
const pageSnapshots=new Map();
const PAGE_SNAPSHOT_TTL=15*60*1000;
let navigationGeneration=0;
function pageSnapshotKey(){
  const user=state.user;
  if(!user?.id)return "";
  const access=[user.role,user.permissions||[],user.data_permissions||[],user.access_features||[]];
  return "offtune-page-snapshots-v1:"+user.id+":"+btoa(unescape(encodeURIComponent(JSON.stringify(access))));
}
function restorePageSnapshots(){
  pageSnapshots.clear();
  try{
    const key=pageSnapshotKey(),saved=key&&JSON.parse(sessionStorage.getItem(key)||"null");
    if(!saved||Date.now()-Number(saved.savedAt)>PAGE_SNAPSHOT_TTL||!saved.pages)return;
    for(const [page,html] of Object.entries(saved.pages)){
      if(typeof html==="string"&&html.length<1500000)pageSnapshots.set(page,html);
    }
  }catch{}
}
function persistPageSnapshots(){
  try{
    const key=pageSnapshotKey();
    if(key)sessionStorage.setItem(key,JSON.stringify({savedAt:Date.now(),pages:Object.fromEntries(pageSnapshots)}));
  }catch{}
}
function clearPageSnapshots(){
  pageSnapshots.clear();
  try{const key=pageSnapshotKey();if(key)sessionStorage.removeItem(key);}catch{}
}
async function api(path, options = {}) {
  const method=String(options.method||"GET").toUpperCase();
  const cacheable=method==="GET"&&path.startsWith("/api/")&&!path.startsWith("/api/auth/")&&path!=="/api/backup";
  if(method!=="GET"){readCache.clear();clearPageSnapshots();}
  if(cacheable){
    const cached=readCache.get(path);
    if(cached&&cached.expires>Date.now()) return structuredClone(await cached.promise);
  }
  const request=(async()=>{
    const headers = { "Content-Type": "application/json", ...(options.headers || {}) };
    if (state.csrf && method!=="GET") headers["X-CSRF-Token"] = state.csrf;
    const res = await fetch(path, { ...options, headers, credentials: "same-origin" });
    const payload = res.status === 204 ? {} : await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(payload.error || "Something went wrong");
    return payload;
  })();
  if(!cacheable) return request;
  const entry={promise:request,expires:Infinity};
  readCache.set(path,entry);
  request.then(()=>{if(readCache.get(path)===entry)entry.expires=Date.now()+10000;},()=>{if(readCache.get(path)===entry)readCache.delete(path);});
  return structuredClone(await request);
}
const post = (path, body) => api(path, { method: "POST", body: JSON.stringify(body) });

function toast(message, error = false) {
  const node = $("#toast"); node.textContent = message; node.className = error ? "show error" : "show";
  clearTimeout(toast.timer); toast.timer = setTimeout(() => node.className = "", 3200);
}
