function applyTheme(theme) {
  const selected = theme === "dark" ? "dark" : "light";
  document.documentElement.dataset.theme = selected;
  const toggle = $("#theme-toggle");
  if (toggle) {
    const toDark = selected !== "dark";
    toggle.innerHTML = `<span aria-hidden="true">${toDark ? "☾" : "☼"}</span>`;
    toggle.setAttribute("aria-label", `Switch to ${toDark ? "dark" : "light"} mode`);
    toggle.title = `Switch to ${toDark ? "dark" : "light"} mode`;
  }
  try { localStorage.setItem("offtune-theme", selected); } catch {}
}
try { applyTheme(localStorage.getItem("offtune-theme") || "light"); } catch { applyTheme("light"); }
try { state.financeDays=Math.max(1,Math.min(365,Number(localStorage.getItem("offtune-finance-days"))||30)); } catch {}
try { state.financePastDueDays=Math.max(1,Math.min(365,Number(localStorage.getItem("offtune-finance-past-due-days"))||30)); state.financeUpcomingDays=Math.max(1,Math.min(365,Number(localStorage.getItem("offtune-finance-upcoming-days"))||30)); } catch {}
$("#theme-toggle").onclick = () => applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");

async function boot() {
  $("#today-label").textContent = new Date().toLocaleDateString("en-IN", { weekday: "short", day: "numeric", month: "short", year: "numeric" });
  try {
    const session = await api("/api/auth/session");
    state.user = session.user; state.csrf = session.csrf; state.workspacePreview=!!session.workspace_preview; state.workspaceOwnerName=session.owner_name||"Owner";
    if (!state.user) return showAuth(session.setup_required);
    await enterApp();
  } catch (e) { showAuth(false); toast(e.message, true); }
}
function showAuth(setup) {
  $("#auth-screen").classList.remove("hidden"); $("#app-shell").classList.add("hidden");
  $("#auth-title").textContent = setup ? "Set up your workspace" : "Welcome back";
  $("#auth-description").textContent = setup ? "Create the founder account. This becomes the workspace owner." : "Sign in to your private workspace.";
  $("#auth-name-wrap").classList.toggle("hidden", !setup);
  $("#auth-name-wrap input").required = setup;
  $("#auth-form input[name=password]").autocomplete = setup ? "new-password" : "current-password";
  $("#auth-submit").textContent = setup ? "Create founder account" : "Sign in";
  $("#auth-form").onsubmit = async e => {
    e.preventDefault(); const f = new FormData(e.currentTarget);
    try {
      await post(setup ? "/api/auth/setup" : "/api/auth/login", Object.fromEntries(f.entries()));
        const session = await api("/api/auth/session");
        state.user = session.user; state.csrf = session.csrf; state.workspacePreview=!!session.workspace_preview; state.workspaceOwnerName=session.owner_name||"Owner";
        if (!state.user) throw new Error("Sign-in completed, but the workspace session could not be loaded. Please try again.");
      await enterApp();
    } catch (err) { toast(err.message, true); }
  };
}
async function enterApp() {
  readCache.clear();
  restorePageSnapshots();
  $("#auth-screen").classList.add("hidden"); $("#app-shell").classList.remove("hidden");
  $("#app-shell").classList.toggle("role-manager",state.user.role==="manager");
  $("#app-shell").classList.toggle("role-employee",state.user.role==="employee");
  renderAccountAvatar();
  $("#role-label").textContent = `${state.user.designation||state.user.job_title||titleCase(state.user.role)} workspace`;
  const preview=$("#workspace-preview-banner"); if(preview){preview.classList.toggle("hidden",!state.workspacePreview);preview.innerHTML=state.workspacePreview?`<span><strong>Previewing ${esc(state.user.name)}’s ${esc(state.user.job_title||titleCase(state.user.role))} workspace</strong><small>Signed in as ${esc(state.workspaceOwnerName)} · Changes here use this team member’s access.</small></span><button type="button" class="button small secondary" id="return-owner-workspace">Return to owner workspace</button>`:"";$("#return-owner-workspace")?.addEventListener("click",async()=>{try{await post("/api/team/preview/end",{});location.reload();}catch(e){toast(e.message,true);}});}
  const common=loadCommon().then(()=>{
    if(state.page==="overview"&&state.data.dashboard?.overview)renderDashboard(state.data.dashboard);
  });
  state.commonPromise=common;
  const settingsPromise=state.user.role==="owner"
    ?api("/api/settings").catch(()=>({})).then(value=>{state.settings=value;applyBrandLogo(value.invoice_logo_data||"");if(state.page==="overview"&&state.data.dashboard?.overview)renderDashboard(state.data.dashboard);return value;})
    :Promise.resolve(state.settings);
  const incentiveRulesPromise=["owner","manager"].includes(state.user.role)
    ?api("/api/incentive/settings").catch(()=>state.incentiveRules).then(value=>{state.incentiveRules=value;return value;})
    :Promise.resolve(state.incentiveRules);
  state.settingsPromise=settingsPromise;
  state.incentiveRulesPromise=incentiveRulesPromise;
  const range=overviewRange(state.overviewPreset);
  const initial={
    dashboard:api("/api/dashboard").then(value=>{state.data.dashboard=value;return value;}),
    overview:loadOverviewData(range.from,range.to),
    targetCourses:state.user.role==="employee"?api("/api/targets/self?month="+encodeURIComponent(today().slice(0,7))).catch(()=>({courses:[]})):Promise.resolve(null),
    range
  };
  renderNav();
  await navigate("overview",initial);
  startMessagePolling();
  api("/api/team/messages").then(messages=>{state.teamMessages=messages;updateNotificationUI();}).catch(()=>{});
  warmWorkspaceRoutes();
}
async function warmWorkspaceRoutes(){
  const role=state.user?.role,permissions=new Set(state.user?.permissions||[]);
  const can=page=>role==="owner"||permissions.has(page);
  const settingsRoutes=role==="owner"?["/api/team","/api/audit","/api/settings/email-sender","/api/settings/reminders","/api/settings/razorpay","/api/settings/ai-provider"]:[];
  const routes=[...settingsRoutes,"/api/targets?month="+encodeURIComponent(today().slice(0,7)),"/api/payments","/api/installments","/api/invoices","/api/expenses","/api/commissions","/api/commissions/payouts","/api/team/messages"];
  if(can("collections"))routes.push("/api/analytics/batches","/api/analytics/courses");
  if(can("followup"))routes.push("/api/followup/settings");
  if(can("analytics"))routes.push("/api/analytics/courses");
  if(role==="owner")routes.push("/api/team/designations","/api/invoice/template","/api/settings/reminders","/api/audit","/api/settings/email-sender","/api/settings/razorpay","/api/settings/ai-provider","/api/settings/ai-models");
  if(role==="manager")routes.push("/api/incentive/team-rules");
  const unique=[...new Set(routes)];
  for(let i=0;i<unique.length;i+=8){
    await Promise.allSettled(unique.slice(i,i+8).map(path=>api(path)));
  }
}
function updateNotificationUI(){
  const button=$("#notification-bell"),badge=$("#notification-count");
  if(!button||!badge)return;
  const canOpen=state.user?.role==="owner"||(state.user?.permissions||[]).includes("messages");
  button.classList.toggle("hidden",!canOpen);
  const now=Date.now();
  const unread=(state.teamMessages||[]).filter(m=>m.direction==="inbox"&&!m.completed&&(!m.remind_at||new Date(m.remind_at).getTime()<=now)).length;
  badge.textContent=unread>99?"99+":String(unread);
  badge.classList.toggle("hidden",!unread);
  button.setAttribute("aria-label",unread?`${unread} unread message${unread===1?"":"s"}. Open messages and reminders`:"Open messages and reminders");
}
function startMessagePolling(){
  clearInterval(state.messagePollTimer);
  state.messagePollTimer=setInterval(async()=>{
    if(!state.user||document.hidden)return;
    const fresh=await api("/api/team/messages").catch(()=>null);
    if(!fresh)return;
    state.teamMessages=fresh;updateNotificationUI();
    if(["overview","messages"].includes(state.page)){
      const panel=$(".team-reminder-panel");if(panel)panel.outerHTML=teamReminderPanel();
    }
  },30000);
}
function renderAccountAvatar(){const node=$("#avatar");if(!node||!state.user)return;const image=state.user.avatar_data;node.innerHTML=image?`<img src="${esc(image)}" alt="${esc(state.user.name)} profile photo">`:`<span>${esc((state.user.name||"A").trim().slice(0,1).toUpperCase())}</span>`;node.title="Change profile photo";node.setAttribute("aria-label","Change profile photo");}
function openProfilePhoto(userId=null){
  const mine=userId==null||Number(userId)===Number(state.user.id);
  const person=mine?state.user:state.team.find(p=>Number(p.id)===Number(userId));
  if(!person)return;
  const preview=person.avatar_data?`<img src="${esc(person.avatar_data)}" alt="Profile photo">`:`<span>${esc((person.name||"?").trim().slice(0,1).toUpperCase())}</span>`;
  openModal(mine?"Edit your profile":`Profile photo · ${person.name}`,`<div class="profile-photo-editor"><div class="profile-photo-preview" id="profile-photo-preview">${preview}</div><label class="button secondary">Choose photo<input type="file" name="photo" accept="image/png,image/jpeg,image/webp" hidden ${mine?"":"required"}></label>${mine?`<label class="full-row profile-name-field">Display name<input name="display_name" maxlength="120" value="${esc(person.name)}" required></label>`:""}<small>PNG, JPEG or WebP · up to 512 KB. Your profile appears in the workspace and team directory.</small></div>`,async form=>{
    const file=form.photo.files?.[0];let dataUrl="";
    if(file){
      if(file.size>512000)throw new Error("Photo must be under 512 KB");
      if(!["image/png","image/jpeg","image/webp"].includes(file.type))throw new Error("Choose a PNG, JPEG or WebP photo");
      dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.onerror=()=>reject(new Error("Could not read that image"));reader.readAsDataURL(file);});
    }else if(!mine)throw new Error("Choose an image first");
    if(mine){
      const name=form.display_name.value.trim();
      if(!name||name.length>120)throw new Error("Enter a name between 1 and 120 characters");
      const result=await post("/api/profile",{name,data_url:dataUrl});state.user=result.user;
      renderAccountAvatar();await navigate(state.page);
    }else{
      if(dataUrl)await post("/api/profile/avatar",{user_id:person.id,data_url:dataUrl});
      person.avatar_data=dataUrl;await navigate("team");
    }
  },"Save profile","Profile updated");
  const input=$("#modal-form [name=photo]");
  input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{$("#profile-photo-preview").innerHTML=`<img src="${esc(String(reader.result||""))}" alt="New profile photo">`;};reader.readAsDataURL(file);};
}
function applyBrandLogo(dataUrl="") {
  const source=dataUrl||"/q-logo.png?v=20261031-qbrand-v1";
  $$('[data-q-brand]').forEach(img=>{if(img.getAttribute("src")!==source)img.src=source;});
}
async function loadCommon() {
  const promises={
    products:api("/api/products").then(value=>{state.products=value;}).catch(()=>{state.products=[];}),
    batches:api("/api/batches").then(value=>{state.batches=value;}).catch(()=>{state.batches=[];}),
    orders:api("/api/orders").then(value=>{state.orders=value;}).catch(()=>{state.orders=[];}),
    team:["owner","manager"].includes(state.user.role)?api("/api/team").then(value=>{state.team=value;}).catch(()=>{state.team=[];}):Promise.resolve([])
  };
  state.commonDataPromises=promises;
  await Promise.all(Object.values(promises));
}
function navItems() {
  const employee=state.user.role==="employee";const items=[{id:"overview",label:"Overview",icon:"▦"},{id:employee?"my-goals":"targets",label:employee?"My goals":state.user.role==="manager"?"Team targets":"Targets",icon:"◎"},{id:"collections",label:"Finance Desk",icon:"↘"},{id:"followup",label:"Follow-up",icon:"◷"},{id:"products",label:"Products",icon:"◇"},{id:"incentives",label:employee?"My incentives":"Incentives",icon:"✦"},{id:"invoices",label:"Invoices",icon:"▤"},{id:"team",label:state.user.role==="owner"?"Team & access":"My team",icon:"♧"},{id:"reports",label:"Reports",icon:"▥"},{id:"batches",label:"Batches",icon:"▦"},{id:"analytics",label:"Course analytics",icon:"◉"},{id:"messages",label:"Messages",icon:"✉"},{id:"expenses",label:"Expenses",icon:"↗"},{id:"my-students",label:"My students",icon:"♧"}];
  if(state.user.role==="owner")return [...items.filter(x=>x.id!=="my-students"),{id:"settings",label:"Settings",icon:"⚙"}];
  if(state.user.role==="employee")items.splice(7,1);
  return items;
}
function renderNav() {
  const available=new Set(state.user?.permissions||[]);
  const visible=navItems().filter(item=>state.user?.role==="owner"||item.id==="overview"||available.has(item.id==="my-goals"?"targets":item.id));
  $("#nav").innerHTML = visible.map(item => `<button class="nav-link ${state.page === item.id ? "active" : ""}" data-page="${item.id}"><span class="nav-icon">${item.icon}</span><span>${item.label}</span></button>`).join("");
  updateNotificationUI();
  $$("#nav [data-page]").forEach(n => n.onclick = () => navigate(n.dataset.page));
}
function workspaceSkeleton(){
  return '<div class="workspace-skeleton" role="status" aria-label="Workspace content is opening"><span class="skeleton-bar wide"></span><span class="skeleton-bar medium"></span><div class="skeleton-grid"><span></span><span></span><span></span></div><span class="skeleton-bar short"></span><span class="skeleton-panel"></span></div>';
}
async function navigate(page,initial=null) {
  const permissionKey=page==="my-goals"?"targets":page;
  if(state.user?.role!=="owner"&&page!=="overview"&&!(state.user?.permissions||[]).includes(permissionKey)){toast("This feature is not enabled for your designation",true);page="overview";}
  const generation=++navigationGeneration;
  state.page = page; renderNav();
  const meta = navItems().find(x => x.id === page); if (!meta) return;
  $("#page-title").textContent = meta.label;
  const content=$("#content");
  const priorSnapshot=pageSnapshots.get(page);
  content.setAttribute("aria-busy","true");
  content.inert=true;
  if(priorSnapshot){
    content.innerHTML="<div class=\"workspace-refreshing\" role=\"status\">Showing the last view while updating…</div>"+priorSnapshot;
    content.classList.add("refreshing");
  }else{
    content.classList.remove("refreshing");
    content.innerHTML=workspaceSkeleton();
  }
  try {
    const commonDependencies={products:["products"],batches:["batches","orders"],analytics:["products","batches","orders"],collections:["products","batches","orders","team"],followup:["orders"],incentives:["orders"],team:["team"],reports:["orders"],settings:["team"]}[page]||[];
    const deferredDependencies=page==="settings"?[state.settingsPromise]:page==="incentives"?[state.incentiveRulesPromise]:[];
    const commonReady=Promise.all([...commonDependencies.map(key=>state.commonDataPromises?.[key]),...deferredDependencies].filter(Boolean));
    const needsDashboard = page === "overview" || page === "team";
    const range = page === "overview" ? initial?.range||overviewRange(state.overviewPreset) : null;
    const [freshDashboard, overview, targetCourses, messages] = await Promise.all([
      needsDashboard ? initial?.dashboard||api("/api/dashboard") : Promise.resolve(null),
      range ? initial?.overview||loadOverviewData(range.from,range.to) : Promise.resolve(null),
      range && state.user.role === "employee" ? initial?.targetCourses||api("/api/targets/self?month="+encodeURIComponent(today().slice(0,7))).catch(()=>({courses:[]})) : Promise.resolve(null),
      page === "messages" ? api("/api/team/messages") : Promise.resolve(null),
      commonReady
    ]);
    if(generation!==navigationGeneration)return;
    const d = freshDashboard || state.data.dashboard || {role:state.user.role};
    if (freshDashboard && (!state.user || d.role !== state.user.role)) {
      throw new Error("Workspace data is out of sync with the signed-in account. Refresh the page to reload your workspace.");
    }
    if (freshDashboard) state.data.dashboard = d;
    if (messages) { state.teamMessages=messages; updateNotificationUI(); }
    if (["overview"].includes(page)) {
      state.overviewFrom=range.from; state.overviewTo=range.to;
      d.overview=overview;
      if (targetCourses) d.targetCourses=targetCourses;
      renderDashboard(d);
    }
    else if (page === "my-goals") { d.targetCourses=await api("/api/targets/self?month="+encodeURIComponent((state.targetsMonth||today().slice(0,7)))); if(generation!==navigationGeneration)return; renderEmployeeGoals(d); }
    else if (page === "my-students") { renderEmployeeStudents(); }
    else if (page === "messages") { $("#content").innerHTML=`<div class="welcome-row"><div><p class="eyebrow">TEAM MESSAGES</p><h2>Your inbox</h2><p class="muted">Owner and manager reminders, plus your conversations.</p></div></div>${teamReminderPanel()}`; }
    else if (page === "targets") await renderTargets();
    else if (page === "collections") await renderCollectionsWorkspace();
    else if (page === "followup") await renderFollowupWorkspace();
    else if (page === "products") renderProducts();
    else if (page === "batches") await renderBatches();
    else if (page === "analytics") await renderAnalytics();
    else if (page === "expenses") await renderExpenses();
    else if (page === "incentives") await renderIncentives();
    else if (page === "invoices") await renderInvoices();
    else if (page === "team") await renderTeam(d);
    else if (page === "reports") await renderReports();
    else if (page === "settings") await renderSettings();
    if(generation===navigationGeneration){pageSnapshots.set(page,content.innerHTML);persistPageSnapshots();}
  } catch (e) { if(generation===navigationGeneration)content.innerHTML = `<div class="notice error">${esc(e.message)}</div>`; }
  finally {
    if(generation===navigationGeneration){content.classList.remove("refreshing");content.inert=false;content.removeAttribute("aria-busy");}
  }
}

function overviewRange(preset=state.overviewPreset) {
  const end=state.overviewTo||today();
  if(preset==="custom")return {from:state.overviewFrom||today(),to:end};
  if(preset==="all")return {from:"2000-01-01",to:today()};
  const dayEnd=new Date(`${today()}T00:00:00`);
  if(preset==="3m"||preset==="6m"||preset==="1y"){
    const months=preset==="3m"?3:preset==="6m"?6:12;
    const first=new Date(dayEnd.getFullYear(),dayEnd.getMonth()-months+1,1);
    return {from:`${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,"0")}-01`,to:today()};
  }
  const days=preset==="7d"?7:preset==="60d"?60:30;
  dayEnd.setDate(dayEnd.getDate()-days+1);
  return {from:`${dayEnd.getFullYear()}-${String(dayEnd.getMonth()+1).padStart(2,"0")}-${String(dayEnd.getDate()).padStart(2,"0")}`,to:today()};
}
async function loadOverviewData(from,to) {
  return api(`/api/dashboard/overview?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
}

function renderDashboard(d) {
  const role=state.user?.role||d.role;
  if (role === "manager") { renderManagerDashboard(d); return; }
  if (role === "employee") {
    renderEmployeeDashboard(d);
    return;
  }
  if (role === "manager") {
    const rows = (d.team || []).map(t => `<tr><td><strong>${esc(t.name)}</strong><small class="subcell">${esc(t.job_title||titleCase(t.role))}</small></td><td>${t.weekly_target?`${t.weekly_conversions} / ${t.weekly_target}${t.weekly_carry_forward?` · ${t.weekly_carry_forward} carried`:""}`:"No target set"}</td><td>${t.target?`${t.conversions} / ${t.target}`:"No target set"}</td><td>${money(t.incentive_pending)}${t.incentive_recovery>0?`<small class="subcell">${money(t.incentive_recovery)} recovery offset</small>`:""}</td><td>${money(t.incentive_paid)}</td><td>${money(t.received)}</td><td>${money(t.pending)}</td></tr>`);
    $("#content").innerHTML = `<div class="welcome-row"><div><p class="eyebrow">TEAM PERFORMANCE</p><h2>Your team at a glance</h2><p class="muted">Conversions, target progress, incentives and collection status for your team.</p></div></div>
      <div class="metric-grid three">${card("Team conversions", d.conversions, "Active orders attributed to your team", "↗", "blue")}${card("Team members", d.team.length, "Across your reporting tree", "♧", "violet")}${card("Current period", new Date().toLocaleDateString("en-IN", {month:"long",year:"numeric"}), "Target tracking period", "◷", "amber")}</div>
      <section class="panel target-checklist-panel"><div class="panel-heading"><div><p class="eyebrow">YOUR COURSE PLAN</p><h3>Your conversions</h3><p>Log your own course conversion here; your team scorecard remains read-only.</p></div></div>${renderTargetCourseChecklist(d.targetCourses?.courses||[])}</section><section class="panel"><div class="panel-heading"><div><h3>Team scorecard</h3><p>Weekly and monthly targets, incentives, collections and dues across your reporting tree.</p></div></div>${table(["Team member","This week · actual / goal","This month · actual / goal","Incentive pending","Incentive paid","Received","Due"],rows,"No team members assigned yet")}</section>${dashboardOrdersSection()}`;
    bindOverviewOrders();
    return;
  }
  renderOwnerDashboard(d);
}
function employeeGoalCard(label,t,source){
  const target=Number(t?.target||0),done=Math.max(0,target-Number(t?.remaining||0)),progress=target?Math.min(100,Math.round(done/target*100)):0;
  const overdue=target>done&&t?.end&&String(t.end)<today();
  return `<article class="employee-goal-card ${target&&progress>=100?"complete":""} ${overdue?"overdue":""}"><div class="employee-goal-top"><span>${esc(label)}${overdue?" · OVERDUE":""}</span><i>${target&&progress>=100?"✓":overdue?"!":"◎"}</i></div><strong>${target?(progress>=100?"Goal complete":`${t.remaining} remaining`):"Not assigned"}</strong><div class="employee-goal-track"><i style="width:${progress}%"></i></div><div class="employee-goal-meta"><span>${target?`${done} / ${target} conversions`:"No target set"}</span><span>${target?`${progress}%`:"—"}</span></div><small>${target?`${esc(source||"Assigned goal")} · ${day(t.start)}–${day(t.end)}${t.carry_forward?` · ${t.carry_forward} carried`:""}`:"Your founder or manager can assign a goal here."}</small></article>`;
}
