  const select=$("#overview-period");select.onchange=async()=>{state.overviewPreset=select.value;$(".overview-custom-fields").classList.toggle("hidden",select.value!=="custom");if(select.value==="custom")return;const r=overviewRange(select.value);state.overviewFrom=r.from;state.overviewTo=r.to;await refreshEmployeeOverview(r);};
