  const pendingScopeCards=()=>["Conversions","Students enrolled","Students to collect from",...(showOutstanding?["Outstanding"]:[])].map(label=>`<article class="metric-card manager-scope-pending"><div class="metric-top"><span>${esc(label)}</span></div><strong>Updating</strong><small>Separate count awaits preview reload</small></article>`).join("");
