  const scopeSummaryHtml=`${o.scopes?"":`<section class="panel notice-panel manager-summary-wait"><div class="notice-icon">◷</div><div><strong>Separate summaries are waiting for the preview update</strong><p>The older service still returns one combined count, so each scope is shown as updating instead of displaying a misleading total.</p></div></section>`}<section class="manager-scope-section"><div class="manager-scope-heading"><div><p class="eyebrow">MY PERFORMANCE</p><h3>Your own conversions</h3><p>Sales credited directly to you.</p></div></div><div class="metric-grid four manager-overview-metrics">${renderScope(scopes.mine)}</div></section>
  <section class="manager-scope-section"><div class="manager-scope-heading"><div><p class="eyebrow">MY TEAM</p><h3>Employee conversions</h3><p>Your reporting team’s activity, separate from your own.</p></div></div><div class="metric-grid four manager-overview-metrics">${renderScope(scopes.team)}</div></section>
  <section class="manager-scope-section company-scope-section"><div class="manager-scope-heading"><div><p class="eyebrow">COMPANY-WIDE</p><h3>All business conversions</h3><p>Includes owner, managers and employees. Conversion totals include owner sales; owner sales do not earn incentive.</p></div></div><div class="metric-grid four manager-overview-metrics">${renderScope(scopes.company)}</div></section>
  ${incentiveSections.join("")}`;
  const target=d.targets?.monthly||{target:0,remaining:0};
  const founderTarget=!!d.targets?.assigned_by&&Number(d.targets.assigned_by)!==Number(state.user.id);
  const targetOverdue=Number(target.target||0)>Number(target.target||0)-Number(target.remaining||0)&&target.end&&String(target.end)<today();
  const rangeLabel=state.overviewPreset==="all"?"Lifetime":`${day(o.from||today())} – ${day(o.to||today())}`;
  const ranges=[["7d","Last 7 days"],["30d","Last 30 days"],["60d","Last 60 days"],["3m","Last 3 months"],["6m","Last 6 months"],["1y","Last 1 year"],["all","Lifetime"],["custom","Custom range"]];
  const custom=state.overviewPreset==="custom";
  const rows=(d.team||[]).map(t=>`<tr><td><strong>${esc(t.name)}</strong><small class="subcell">${esc(titleCase(t.role||"employee"))}</small></td><td>${t.weekly_target?`${t.weekly_conversions} / ${t.weekly_target}${t.weekly_carry_forward?` · ${t.weekly_carry_forward} carried`:""}`:"No target set"}</td><td>${t.target?`${t.conversions} / ${t.target}`:"No target set"}</td>${showTeamIncentives?`<td>${money(t.incentive_pending)}</td><td>${money(t.incentive_paid)}</td>`:""}${showOutstanding?`<td>${money(t.outstanding)}</td>`:""}</tr>`);
  $("#content").innerHTML=`<section class="manager-target-hero ${targetOverdue?"overdue":""}"><div class="manager-target-copy"><p class="eyebrow">${founderTarget?"FOUNDER ASSIGNED GOAL":"YOUR MONTHLY GOAL"}${targetOverdue?" · OVERDUE":""}</p><h2>Team target</h2><p>${founderTarget?"Assigned by the founder · pinned to your overview":"Your monthly conversion goal, with weekly carry-forward."}</p><div class="manager-target-amount">${target.target?`${Math.max(0,target.remaining)} <small>conversions remaining</small>`:"No target assigned yet"}</div>${target.target?`<div class="manager-target-track"><i style="width:${Math.min(100,Math.round((target.target-target.remaining)/target.target*100))}%"></i></div><small>${target.target-target.remaining} of ${target.target} complete${target.carry_forward?` · ${target.carry_forward} carried forward`:""}</small>`:""}</div><span class="manager-target-pulse">◎</span></section>
  <section class="overview-period-panel"><div><p class="eyebrow">REPORTING PERIOD</p><strong>${esc(rangeLabel)}</strong><small>Conversion, student and incentive activity follow this date range.</small></div><form id="overview-period-form"><label class="overview-period-select">Period<select id="overview-period">${ranges.map(([value,label])=>`<option value="${value}" ${state.overviewPreset===value?"selected":""}>${label}</option>`).join("")}</select></label><div class="overview-custom-fields ${custom?"":"hidden"}"><label>From<input type="date" id="overview-from" value="${esc(state.overviewFrom||o.from||today())}" max="${esc(today())}"></label><label>To<input type="date" id="overview-to" value="${esc(state.overviewTo||o.to||today())}" max="${esc(today())}"></label><button class="button primary small" type="submit">Apply dates</button></div></form></section>
  ${scopeSummaryHtml}${o.company_financials?`<section class="manager-scope-section"><div class="manager-scope-heading"><div><p class="eyebrow">OWNER-SHARED FINANCIAL VIEW</p><h3>Company financial totals</h3><p>Enabled by the owner for this designation · ${esc(day(o.from||today()))} – ${esc(day(o.to||today()))}</p></div></div><div class="metric-grid ${showOutstanding?"three":"two"} manager-overview-metrics">${card("Company sales value",money(o.company_financials.sales),"All business enrollments","order","blue")}${card("Company collected",money(o.company_financials.received),"Payments in selected period","coin","green")}${showOutstanding?card("Company outstanding",money(o.company_financials.outstanding),"Open balance on enrollments in range","clock","amber"):""}</div></section>`:""}
  <div class="manager-overview-actions"><button class="button secondary" data-page="targets">Manage team targets →</button><button class="button secondary" data-page="incentives">Open incentive ledger →</button><button class="button secondary" data-page="followup">Open follow-up queue →</button></div>
  <section class="panel target-checklist-panel"><div class="panel-heading"><div><p class="eyebrow">YOUR COURSE PLAN</p><h3>Your conversions</h3><p>Log your own course conversion here; your team scorecard remains read-only.</p></div></div>${renderTargetCourseChecklist(d.targetCourses?.courses||[])}</section>
  <section class="panel"><div class="panel-heading"><div><h3>Team scorecard</h3><p>Conversion goals, incentive balance and outstanding collections across your reporting tree.</p></div><button class="text-button" data-page="targets">Manage employee targets →</button></div>${table(["Team member","This week · actual / goal","This month · actual / goal",...(showTeamIncentives?["Incentive due","Incentive paid"]:[]),...(showOutstanding?["Outstanding"]:[])],rows,"No team members assigned yet")}</section>${dashboardOrdersSection()}`;
  const select=$("#overview-period");
  select.onchange=async()=>{state.overviewPreset=select.value;$(".overview-custom-fields").classList.toggle("hidden",select.value!=="custom");if(select.value==="custom")return;const range=overviewRange(select.value);state.overviewFrom=range.from;state.overviewTo=range.to;await refreshOverview(range);};
  $("#overview-period-form").onsubmit=async event=>{event.preventDefault();state.overviewPreset="custom";state.overviewFrom=$("#overview-from").value;state.overviewTo=$("#overview-to").value;if(!state.overviewFrom||!state.overviewTo||state.overviewFrom>state.overviewTo){toast("Choose a valid date range",true);return;}await refreshOverview({from:state.overviewFrom,to:state.overviewTo});};
