    const renderInvoiceStage=(stage,index)=>`<article class="emi-flow-node" data-emi-stage><span class="emi-flow-marker">${String(index+1).padStart(2,"0")}</span><details class="emi-flow-details"><summary><span class="emi-flow-title" data-stage-title>${esc(stage.label||"Reminder step")}</span><span class="emi-flow-day" data-stage-day>${Number(stage.offset_days)<0?`D−${Math.abs(Number(stage.offset_days))}`:Number(stage.offset_days)===0?"DUE":`D+${Number(stage.offset_days)}`}</span><span class="emi-flow-edit">Edit</span></summary><div class="emi-stage-fields"><label>Days from due date<input data-stage-field="offset_days" type="number" min="-365" max="3650" value="${Number(stage.offset_days)||0}" required><small>Minus = before · 0 = due date · plus = after</small></label><label>Stage name<input data-stage-field="label" value="${esc(stage.label||"")}" maxlength="60" required></label><label class="full-row">Email subject<input data-stage-field="subject" value="${esc(stage.subject||"")}" maxlength="180" required></label><label class="full-row">Message<textarea data-stage-field="body" rows="3" maxlength="2000" required>${esc(stage.body||"")}</textarea></label></div></details><button type="button" class="button small secondary" data-invoice-stage-remove aria-label="Remove ${esc(stage.label||"reminder step")}" title="Remove step">×</button></article>`;
