  const footer=form.footer_text.value.trim()||"Thank you for choosing OFFTune Business Desk.";
  const website=String(state.settings?.business_website||"").replace(/^https?:\/\/(www\.)?/i,"").replace(/\/$/,"");
  const details=[form.show_phone.checked?(state.settings?.business_phone||""):"",form.show_email.checked?(state.settings?.business_email||""):"",form.show_website.checked?website:""].filter(Boolean).join(" · ");
