  $("#target-add-course").onclick=()=>{const used=new Set($$(".target-course-row-edit select",form).map(s=>Number(s.value)));const next=available.find(p=>p.active&&!used.has(Number(p.id)));if(!next){toast("All active courses are already added",true);return;}$("#target-course-editor-list .target-editor-empty")?.remove();$("#target-course-editor-list").insertAdjacentHTML("beforeend",targetCourseEditorRow(next.id,1,available));bindTargetCourseEditor(form,refresh);refresh();};
