function targetCourseEditorRow(selectedId,count,products){const options=products.map(p=>`<option value="${p.id}" ${Number(selectedId)===Number(p.id)?"selected":""}>${esc(p.name)}</option>`).join("");const selected=products.find(p=>Number(p.id)===Number(selectedId));return `<div class="target-course-row-edit"><select aria-label="Course" required>${options}</select><input aria-label="Monthly conversions" type="number" min="0" max="100000" step="1" value="${Number(count)||0}" required><small data-course-price>${money(selected?.price||0)} · ${Number(selected?.commission_rate)||0}% incentive</small><button type="button" class="target-course-remove" aria-label="Remove course">×</button></div>`;}
