  const balance=orders.reduce((n,o)=>n+Number(String(o.pending||0).replace(/[^0-9.-]/g,"")),0);
  const incentiveDue=commissions.reduce((n,c)=>n+Number(c.balance||0),0);
  const periodPayments=payments.filter(p=>within(p.date));
  const daily=new Map();period.forEach(o=>{const k=state.reportGroup==="year"?o.date.slice(0,4):state.reportGroup==="month"?o.date.slice(0,7):o.date.slice(0,10);daily.set(k,(daily.get(k)||0)+1);});
  const max=Math.max(1,...daily.values());const bars=[...daily.entries()].sort((a,b)=>a[0].localeCompare(b[0])).slice(-30).map(([key,count])=>`<div class="report-flow-month" title="${esc(key)} · ${count} conversions"><div class="report-flow-bars single"><span class="report-flow-bar enrollments" style="height:${Math.max(5,Math.round(count/max*100))}%"></span></div><small>${esc(key.length===10?key.slice(8):key.slice(5))}</small></div>`).join("");
  const courseMap=new Map();period.forEach(o=>(o.products||[]).forEach(p=>{const item=courseMap.get(p.name)||{name:p.name,count:0};item.count+=Number(p.quantity||1);courseMap.set(p.name,item);}));
