    const prevTo=shift(from,-1),prevFrom=shift(prevTo,-rangeDays+1);
    const prevOrders=orders.filter(o=>within(o.date,prevFrom,prevTo)&&courseItems(o).length);
    const booked=periodOrders.reduce((n,o)=>n+valueOf(o),0),prevBooked=prevOrders.reduce((n,o)=>n+valueOf(o),0);
    const periodPayments=payments.filter(p=>within(p.date,from,until));
    const prevPayments=payments.filter(p=>within(p.date,prevFrom,prevTo));
