    const refunds=list=>list.filter(p=>p.type==="refund").reduce((n,p)=>n+Number(p.amount||0),0);
    const cash=receipts(periodPayments)-refunds(periodPayments),prevCash=receipts(prevPayments)-refunds(prevPayments);
