    const periodLabel=fmt(from)+" – "+fmt(until),range=state.reportRange;
    const rangeButtons=[["30d","30 days"],["90d","90 days"],["12m","12 months"],["ytd","This year"],["all","All time"],["custom","Custom"]].map(([k,label])=>'<button type="button" data-report-range="'+k+'" class="'+(range===k?"active":"")+'" aria-pressed="'+(range===k)+'">'+label+'</button>').join("");
