    $$("[data-report-range]").forEach(b=>b.onclick=()=>{state.reportRange=b.dataset.reportRange;if(state.reportRange==="custom"){state.reportFrom=from;state.reportTo=until;}else state.reportGroup=state.reportRange==="30d"?"day":state.reportRange==="all"?"year":state.reportRange==="90d"?"day":"month";renderReports();});
    $$("[data-report-group]").forEach(b=>b.onclick=()=>{state.reportGroup=b.dataset.reportGroup;renderReports();});
