async function exportWorkspaceBackup(){
  const confirmed=confirm("This backup contains student contact details, orders, payment history and team records. Save it only to a secure location. Continue?");
  if(!confirmed)return;
  try{
    const backup=await api("/api/backup");
    const blob=new Blob([JSON.stringify(backup,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`offtune-workspace-export-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Workspace export downloaded");
  }catch(error){toast(`Backup failed: ${error.message}`,true);}
}
