  root.querySelector("[data-ai-close]").onclick=close;
  const liveToggle=root.querySelector("[data-live-toggle]"),liveState=root.querySelector("[data-live-state]"),livePanel=root.querySelector(".ai-live-panel"),liveOrb=root.querySelector("[data-live-orb]"),liveModelPicker=root.querySelector("[data-live-model]"),liveCheck=root.querySelector("[data-live-check]"),liveProposal=root.querySelector("[data-live-proposal]"),liveSizeButton=root.querySelector("[data-live-size]"),voiceStatus=root.querySelector("[data-ai-voice-status]"); let shareWorkspaceData=false; const contextToggle=root.querySelector("[data-ai-context-toggle]"); const updateContextToggle=()=>{if(!contextToggle)return;contextToggle.setAttribute("aria-pressed",shareWorkspaceData?"true":"false");contextToggle.textContent=shareWorkspaceData?"Workspace data on":"Workspace data off";contextToggle.classList.toggle("is-on",shareWorkspaceData);}; contextToggle?.addEventListener("click",()=>{shareWorkspaceData=!shareWorkspaceData;updateContextToggle();});
