  openModal(`Set target · ${person?.name||"Employee"}`,`<div class="form-grid"><label>Target period<select name="period_type"><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><label class="target-week">Pick a date in the week<input type="date" name="weekly_period" value="${todayDate}" required></label><label class="target-month hidden">Month<input type="month" name="monthly_period" value="${month}" required disabled></label><label>Conversion goal<input name="conversion_target" type="number" min="0" step="1" value="0" required></label></div><p class="field-hint target-rollover-note">Monthly goals are split across the weeks in that month. Any missed conversions carry into the next week automatically. A weekly goal replaces that week’s automatic amount; its shortfall also carries forward.</p>`,async form=>{const kind=form.period_type.value;await post("/api/targets",{user_id:userId,period_type:kind,period:kind==="weekly"?form.weekly_period.value:form.monthly_period.value,conversion_target:Number(form.conversion_target.value)});});
  $("[name=period_type]").onchange=e=>{const weekly=e.target.value==="weekly";$(".target-week").classList.toggle("hidden",!weekly);$(".target-month").classList.toggle("hidden",weekly);$("[name=weekly_period]").disabled=!weekly;$("[name=monthly_period]").disabled=weekly;};
