async function openPayout(userId) {
  if(state.user.role!=="owner"){toast("Only the business owner can record an incentive payout",true);return;}
  try{state.incentiveEvents=await api("/api/commissions");}catch(e){toast(e.message,true);return;}
  const person=state.team.find(p=>p.id===userId);
  const balance=(state.incentiveEvents||[]).filter(e=>e.employee_id===userId).reduce((t,e)=>t+Number(e.balance||0),0);
  openModal(`Pay incentive · ${person?.name||"Team member"}`,`<div class="notice compact">Unpaid balance: <strong>${money(balance)}</strong></div><div class="form-grid"><label>Paid on<input name="paid_on" type="date" value="${today()}" max="${today()}" required></label><label>Amount to pay<input name="amount" type="number" min="0.01" max="${Math.max(balance,0)}" step="0.01" value="${Math.max(balance,0).toFixed(2)}" required></label><label>Payment method<select name="method"><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Cheque</option><option>Other</option></select></label><label>Reference<input name="reference" maxlength="120" placeholder="Transaction ID / voucher"></label><label class="full-row">Notes<textarea name="notes" rows="2" maxlength="500"></textarea></label></div><p class="field-hint">A partial payout is allowed; the remaining amount stays in the follow-up list.</p>`,async form=>post("/api/commissions/payout",{user_id:userId,paid_on:form.paid_on.value,amount:Number(form.amount.value),method:form.method.value,reference:form.reference.value,notes:form.notes.value}));
}
function openCommissionDueDate(eventId){
  if(state.user.role!=="owner"){toast("Only the business owner can change an incentive payout date",true);return;}
  const item=(state.incentiveEvents||[]).find(e=>e.id===eventId);if(!item)return;
  openModal(`Change payout date · ${item.employee}`,`<div class="form-grid"><label class="full-row">New payout due date<input type="date" name="due_date" value="${esc(item.due_date||today())}" required></label></div><p class="field-hint">Only the unpaid balance’s payout deadline changes. Earned amount, original sale and recorded payments stay intact.</p>`,async form=>post("/api/commissions/due-date",{event_id:eventId,due_date:form.due_date.value}),"Save date");
}
function initAmbientParticles(){
  const canvas=$("#ambient-particle-field");if(!canvas||!canvas.getContext)return;const ctx=canvas.getContext("2d");if(!ctx||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
  let width=0,height=0,dpr=1,last=0,visible=0,particleTheme="";const pointer={x:0,y:0,targetX:0,targetY:0,alpha:0,targetAlpha:0};let particles=[];
  const rebuildParticles=()=>{particleTheme=document.documentElement.dataset.theme||"light";const colors=particleTheme==="dark"?[[119,177,207],[105,184,154],[192,174,128],[196,133,139]]:[[68,126,165],[63,141,105],[158,119,57],[164,101,108]];const radius=Math.min(440,Math.max(285,width*.32));particles=Array.from({length:118},()=>({angle:Math.random()*Math.PI*2,distance:Math.sqrt(Math.random())*radius,size:.55+Math.random()*1.25,phase:Math.random()*Math.PI*2,speed:.12+Math.random()*.25,drift:3+Math.random()*11,alpha:particleTheme==="dark"?.10+Math.random()*.22:.075+Math.random()*.16,color:colors[Math.floor(Math.random()*colors.length)]}));};
  const resize=()=>{dpr=Math.min(window.devicePixelRatio||1,2);width=window.innerWidth;height=window.innerHeight;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);canvas.style.width=`${width}px`;canvas.style.height=`${height}px`;ctx.setTransform(dpr,0,0,dpr,0,0);rebuildParticles();};
  const interactive="button,a,input,select,textarea,[role=button],[data-action],[data-page],[data-finance-tab],[data-collection-toggle],[data-collection-view],[data-outstanding-filter],[data-due-batch]";
  document.addEventListener("pointermove",event=>{if(event.pointerType!=="mouse")return;pointer.targetX=event.clientX;pointer.targetY=event.clientY;const overControl=event.target instanceof Element&&event.target.closest(interactive);pointer.targetAlpha=overControl?0:.82;},{passive:true});
  document.addEventListener("pointerout",event=>{if(event.pointerType==="mouse"&&!event.relatedTarget)pointer.targetAlpha=0;},{passive:true});
  window.addEventListener("blur",()=>{pointer.targetAlpha=0;});window.addEventListener("resize",resize,{passive:true});resize();
  const draw=now=>{requestAnimationFrame(draw);if(now-last<32)return;last=now;if((document.documentElement.dataset.theme||"light")!==particleTheme)rebuildParticles();const t=now/1000;pointer.x+=(pointer.targetX-pointer.x)*.075;pointer.y+=(pointer.targetY-pointer.y)*.075;pointer.alpha+=(pointer.targetAlpha-pointer.alpha)*(pointer.targetAlpha? .07:.42);if(pointer.alpha<.004){if(visible){ctx.clearRect(0,0,width,height);visible=0;}return;}visible=1;ctx.clearRect(0,0,width,height);for(const p of particles){const drift=Math.sin(t*p.speed+p.phase)*p.drift,angle=p.angle+t*(p.speed*.18),distance=p.distance+Math.cos(t*p.speed+p.phase)*7,x=pointer.x+Math.cos(angle)*distance+drift,y=pointer.y+Math.sin(angle)*distance+drift*.7;if(x<0||y<0||x>width||y>height)continue;const [r,g,b]=p.color;ctx.beginPath();ctx.fillStyle=`rgba(${r},${g},${b},${p.alpha*pointer.alpha})`;ctx.arc(x,y,p.size,0,Math.PI*2);ctx.fill();}};requestAnimationFrame(draw);
}
function openInvoice() {
  const employee=state.user.role==="employee";
  const issued=new Set((state.invoices||[]).filter(i=>i.invoice_kind!=="installment").map(i=>Number(i.order_id)));
  const orders=state.orders.filter(o=>(!employee||o.can_manage)&&o.status!=="void"&&!issued.has(Number(o.id))&&Array.isArray(o.products)&&o.products.length);
  if(!orders.length){toast("Record a course or product sale first, or check whether every order already has an invoice",true);return;}
  const description=o=>o.products.map(p=>`${p.name}${p.type&&p.type!=="course"?` · ${titleCase(p.type)}`:""}${p.batch?` · ${p.batch}`:""}`).join(" · ");
  const options=orders.map(o=>`<option value="${o.id}">${esc(o.order_no)} · ${esc(o.customer)} · ${esc(description(o))}${employee?"":` · ${money(o.total)}`}</option>`).join("");
  const preview=o=>o?`<div class="invoice-draft-card"><div><span class="label">BILL TO</span><strong>${esc(o.customer)}</strong><small>${esc(o.order_no)} · ${day(o.date)}</small></div><div class="invoice-draft-items">${o.products.map(p=>`<span>${financeIcon("product")}<b>${esc(p.name)}</b><small>${esc(titleCase(p.type||"product"))}${p.batch?` · ${esc(p.batch)}`:""}</small></span>`).join("")}</div>${employee?`<small>Invoice amounts are taken from the issued invoice record.</small>`:`<div class="invoice-draft-totals"><span>Order total <b>${money(o.total)}</b></span><span>Received <b>${money(o.received)}</b></span><span>Balance due <b>${money(o.pending)}</b></span></div>`}</div>`:`<p class="muted">Choose an order to preview its invoice items.</p>`;
  openModal("Create invoice",`<div class="invoice-create-intro"><span class="invoice-create-icon">▤</span><div><strong>Choose an order to prepare its invoice</strong><small>Sales appear here first. Select one course or product order, review the preview, then save it to the invoice register. Saving does not send an email.</small></div></div><label class="settings-field">Choose course or product order<select name="order_id" data-invoice-order required><option value="">Select an order</option>${options}</select></label><div id="invoice-draft-preview">${preview(null)}</div><div class="notice warning compact"><strong>Before saving:</strong> Check the preview and business details. You can open the saved invoice, preview it, and send it from the invoice register.</div>`,async form=>post("/api/invoices",{order_id:Number(form.order_id.value)}),"Save invoice","Invoice saved in the register");
  const selector=$("[data-invoice-order]");
  const updatePreview=()=>{const order=orders.find(o=>Number(o.id)===Number(selector.value));$("#invoice-draft-preview").innerHTML=preview(order);};
  selector.onchange=updatePreview;
}

document.addEventListener("click",e=>{const trigger=e.target.closest("[data-student-profile]");if(!trigger)return;e.preventDefault();e.stopImmediatePropagation();openStudentProfile(Number(trigger.dataset.studentProfile));},true);
document.addEventListener("keydown",e=>{if(e.key!=="Enter"&&e.key!==" ")return;const trigger=e.target.closest?.("[data-student-profile]");if(!trigger)return;e.preventDefault();e.stopImmediatePropagation();openStudentProfile(Number(trigger.dataset.studentProfile));},true);
document.addEventListener("click", e => {
  if(e.target.closest("#avatar")){openProfilePhoto();return;}
  if(e.target.closest("#notification-bell")){navigate("messages");return;}
  if(e.target.closest('[data-action="open-ai-assistant"]')){openAIAssistant();return;}
  const nav=e.target.closest("[data-page]"); if(nav){navigate(nav.dataset.page);return;}
  const action=e.target.closest("[data-action]")?.dataset.action; if(!action)return;
  if(action==="clear-employee-batch"){state.employeeBatchFilter="";state.employeeCourseFilter="";navigate("my-students");return;}
  if(action==="workspace-switcher"){openWorkspaceSwitcher();return;}
  if(action.startsWith("print-invoice:")){printInvoice(Number(action.split(":")[1]));return;}
  if(action.startsWith("email-invoice:")){openInvoiceSendPreview(Number(action.split(":")[1]));return;}
  if(action==="customize-invoice"){openInvoiceTemplateEditor();return;}
  if(action.startsWith("delete-invoice:")){deleteInvoice(Number(action.split(":")[1]));return;}
  if(action.startsWith("delete-expense:")){confirmDeleteExpense(Number(action.split(":")[1]));return;}
  if(action.startsWith("commission-date:")){openCommissionDueDate(Number(action.split(":")[1]));return;}
  if(action.startsWith("mark-course-conversion:")){openTargetConversion(Number(action.split(":")[1]));return;}
  if(action.startsWith("reporting:")){openReportingLine(Number(action.split(":")[1]));return;}
  if(action.startsWith("team-incentive:")){openManagerTeamRule(Number(action.split(":")[1]));return;}
  if(action.startsWith("edit-user:")){openTeamEdit(Number(action.split(":")[1]));return;}
  if(action.startsWith("edit-photo:")){openProfilePhoto(Number(action.split(":")[1]));return;}
  if(action.startsWith("edit-designation:")){openDesignationEditor(Number(action.split(":")[1]));return;}
  if(action.startsWith("delete-designation:")){deleteDesignation(Number(action.split(":")[1]));return;}
  if(action==="new-designation"){openDesignationEditor();return;}
  if(action.startsWith("reset-user-password:")){openTeamPasswordReset(Number(action.split(":")[1]));return;}
  if(action.startsWith("preview-workspace:")){previewTeamWorkspace(Number(action.split(":")[1]));return;}
  if(action.startsWith("send-team-message:")){openTeamMessage(Number(action.split(":")[1]));return;}
  if(action==="new-team-message"){openTeamMessage();return;}
  if(action.startsWith("complete-team-message:")){const id=Number(action.split(":")[1]);post("/api/team/messages/complete",{id}).then(()=>navigate(state.page)).catch(err=>toast(err.message,true));return;}
  if(action.startsWith("user-status:")){const [userId,mode]=action.split(":").slice(1),person=(state.data.team||[]).find(x=>Number(x.id)===Number(userId));if(mode==="on"){post("/api/team/status",{user_id:Number(userId),active:true}).then(async()=>{await loadCommon();await navigate(state.page);toast("Team access restored");}).catch(err=>toast(err.message,true));return;}openModal(`Remove ${person?.name||"team member"} from team`,`<div class="notice warning compact"><strong>Sign-in access will be turned off.</strong> Past sales, incentive records and payment history will stay in the workspace. To remove a manager, first reassign their direct reports.</div><p class="field-hint">You can restore access later from the inactive team list.</p>`,async()=>post("/api/team/status",{user_id:Number(userId),active:false}),"Remove access","Team member removed; access disabled");return;}
  if(action.startsWith("edit-profile-installment:")){openProfileScheduleEditor(Number(action.split(":")[1]));return;}
  if(action.startsWith("edit-installment:")){openInstallmentDate(Number(action.split(":")[1]));return;}
  if(action.startsWith("manage-order-batches:")){openOrderBatches(Number(action.split(":")[1]));return;}
  if(action.startsWith("batch-students:")){openBatchStudents(Number(action.split(":")[1]));return;}
  if(action.startsWith("remove-batch:")){const id=Number(action.split(":")[1]),batch=state.batches.find(item=>Number(item.id)===id);if(!batch)return;openModal(`Remove batch · ${batch.name}`,`<div class="notice warning compact"><strong>Are you sure you want to remove this batch?</strong> If students are enrolled, it will be archived and closed to new sales. If empty, it will be deleted. Student and payment history stays safe.</div><label class="delete-confirm-check"><input name="confirmed" type="checkbox" required><span>Yes, remove this batch</span></label><p class="field-hint">Archived batches can be restored from the Archived filter.</p>`,async form=>post("/api/batches/remove",{id,confirmed:form.confirmed.checked}),"Remove batch","Batch removed; linked student and payment history is preserved");return;}
  if(action==="retry-incentives"){renderIncentives();return;}
  if(action==="new-sale")openSale(); else if(action==="new-payment")openPayment(); else if(action==="new-product")openProduct(); else if(action==="new-batch")openBatch(); else if(action.startsWith("edit-product:"))openProduct(Number(action.split(":")[1])); else if(action.startsWith("edit-batch:"))openBatch(Number(action.split(":")[1])); else if(action==="new-expense")openExpense(); else if(action==="new-user")openUser(); else if(action==="new-invoice")openInvoice(); else if(action.startsWith("monthly-target:"))openMonthlyTarget(Number(action.split(":")[1])); else if(action.startsWith("delete-monthly-target:"))confirmDeleteMonthlyTarget(Number(action.split(":")[1])); else if(action.startsWith("target:"))openTarget(Number(action.split(":")[1])); else if(action.startsWith("payout:"))openPayout(Number(action.split(":")[1]));
});
$("#signout").onclick=async()=>{try{await post("/api/auth/logout",{});}catch{}state.user=null;state.csrf=null;location.reload();};
initAmbientParticles();
boot();
